/* AYYY Weather Tree · SVG generated by deterministic seasonal model. */
(function installTree(root){
'use strict';
const STAGES=[
{name:'Январь',season:'winter',density:0,label:'Зимний покой · голые ветви',colors:['#b4b9ad','#dedfda']},
{name:'Февраль',season:'winter',density:0,label:'Зима · ветви и иней',colors:['#b4b9ad','#dedfda']},
{name:'Март',season:'spring',density:.08,label:'Первые почки',colors:['#b9ca83','#d6c88c','#9eb47b']},
{name:'Апрель',season:'spring',density:.53,label:'Молодая зелень',colors:['#a3bd75','#c9ce7c','#8bad73','#ded5a0']},
{name:'Май',season:'spring',density:.81,label:'Свежая густая листва',colors:['#79a275','#afbe74','#719a79','#c2c77f']},
{name:'Июнь',season:'summer',density:.97,label:'Пышная летняя крона',colors:['#578e6e','#7ea66f','#9bb66a','#4c836c']},
{name:'Июль',season:'summer',density:1,label:'Лето · полная зелень',colors:['#4d8366','#82a46c','#adc078','#598f71']},
{name:'Август',season:'summer',density:.93,label:'Позднее лето',colors:['#59876c','#96a46a','#c0ae69','#648b6d']},
{name:'Сентябрь',season:'autumn',density:.85,label:'Начало золотой осени',colors:['#72936e','#c7ad65','#e5b05d','#a48e66','#cf9551']},
{name:'Октябрь',season:'autumn',density:.63,label:'Золотые листья · листопад',colors:['#daa352','#e4bd67','#d7874c','#b67c43','#a9a06c']},
{name:'Ноябрь',season:'autumn',density:.11,label:'Поздний листопад',colors:['#ad7948','#c19157','#887a61','#d8aa70']},
{name:'Декабрь',season:'winter',density:0,label:'Декабрь · деревья без листвы',colors:['#b2b8ad','#c2b9ad']}
];
const rng=(s)=>()=>{s=(Math.imul(s,1664525)+1013904223)>>>0;return s/4294967296;};
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
function stage(month,latitude=50){
 const m=clamp(Number.isFinite(Number(month))?Math.floor(Number(month)):7,1,12);
 const effective=Number(latitude)<-15?(m+5)%12+1:m;
 const out=STAGES[effective-1];
 return {...out,month:m,ecologicalMonth:effective,hemisphere:Number(latitude)<-15?'south':'north'};
}
const clusters=[[208,440,131,103],[305,331,156,126],[459,281,165,124],[598,316,169,116],[714,419,142,108],[521,449,174,124],[343,490,163,102],[167,551,110,76],[732,531,102,79],[460,380,176,133],[357,260,128,93],[570,237,122,82]];
function canopy(month,latitude=50){
 const data=stage(month,latitude),rnd=rng(40970),cs=data.colors,d=data.density;
 if(d===0)return '<svg class="ww-tree-foliage" viewBox="0 0 900 1000" aria-hidden="true"></svg>';
 let washes='',leaves='',twigs='';
 for(let k=0;k<clusters.length;k++){
  const [cx,cy,rx,ry]=clusters[k],sz=.6+d*.55;
  washes+=`<path d="M${cx-rx*sz} ${cy}Q${cx-rx*.91*sz} ${cy-ry*.85*sz} ${cx-rx*.28*sz} ${cy-ry*.94*sz}T${cx+rx*.49*sz} ${cy-ry*.65*sz}Q${cx+rx*sz} ${cy-ry*.38*sz} ${cx+rx*.92*sz} ${cy+ry*.17*sz}T${cx+rx*.20*sz} ${cy+ry*.87*sz}Q${cx-rx*.53*sz} ${cy+ry*.73*sz} ${cx-rx*sz} ${cy}Z" fill="${cs[k%cs.length]}" opacity="${(.12+d*.26).toFixed(2)}" filter="url(#ww-tree-paint)"/>`;
 }
 const count=Math.round(1520*d);
 for(let n=0;n<count;n++){
  const [cx,cy,rx,ry]=clusters[Math.floor(rnd()*clusters.length)],a=rnd()*Math.PI*2,rr=Math.sqrt(rnd())*(.83+d*.1);
  const x=cx+Math.cos(a)*rx*rr,y=cy+Math.sin(a)*ry*rr;
  if(x<55||x>850||y<118||y>640)continue;
  const radius=(4.4+rnd()*8.6)*(d<.19?.64:1),rotate=Math.floor(rnd()*360);
  const color=cs[Math.floor(rnd()*cs.length)],alpha=(.42+rnd()*.42).toFixed(2);
  const shape=n%5===0?`<ellipse cx="0" cy="0" rx="${(radius*.62).toFixed(1)}" ry="${radius.toFixed(1)}"/>`:
   `<path d="M0 ${(-radius).toFixed(1)}Q${(radius*.91).toFixed(1)} ${(-radius*.6).toFixed(1)} ${radius.toFixed(1)} 0Q${(radius*.6).toFixed(1)} ${(radius*.75).toFixed(1)} 0 ${radius.toFixed(1)}Q${(-radius*.8).toFixed(1)} ${(radius*.4).toFixed(1)} ${(-radius).toFixed(1)} 0Q${(-radius*.56).toFixed(1)} ${(-radius*.72).toFixed(1)} 0 ${(-radius).toFixed(1)}Z"/>`;
  leaves+=`<g transform="translate(${x.toFixed(1)} ${y.toFixed(1)}) rotate(${rotate})" fill="${color}" fill-opacity="${alpha}" stroke="#4f6650" stroke-opacity=".08" stroke-width=".55">${shape}</g>`;
  if(n%17===0)twigs+=`<path d="M${x.toFixed(1)} ${y.toFixed(1)}l${(rnd()*7-3).toFixed(1)} ${(rnd()*15+3).toFixed(1)}" stroke="#58554a" opacity=".21" fill="none" stroke-width=".9"/>`;
 }
 return `<svg class="ww-tree-foliage" viewBox="0 0 900 1000" xmlns="http://www.w3.org/2000/svg" aria-hidden="true"><defs><filter id="ww-tree-paint" x="-6%" y="-6%" width="112%" height="112%"><feTurbulence baseFrequency=".023" numOctaves="2" seed="29" result="n"/><feDisplacementMap in="SourceGraphic" in2="n" scale="12"/></filter></defs><g class="ww-tree-wash">${washes}</g><g class="ww-tree-leaves">${leaves}</g><g>${twigs}</g></svg>`;
}
const snowCaps='<svg class="ww-tree-snowcap" viewBox="0 0 900 1000" xmlns="http://www.w3.org/2000/svg" aria-hidden="true"><g stroke="#d5e4e6" stroke-width=".8" fill="#f7fcff" fill-opacity=".86"><path d="M425 625q25-7 51 1l-6 11-32-2Z"/><path d="M459 562q32-12 53-3l-8 11-40 1Z"/><path d="M270 395q42-11 85 2l-19 10-44-5Z"/><path d="M574 380q35-12 75-2l-17 13-50-3Z"/><path d="M354 282q37-11 66-4l-12 9-40 1Z"/><path d="M659 485q28-11 54-3l-12 11-30 1Z"/><path d="M410 833q22-7 55-3l7 10-54-2Z"/></g></svg>';
function falling(month,latitude=50){
 const s=stage(month,latitude);if(s.season!=='autumn')return '';
 const rnd=rng(42852),count=s.ecologicalMonth===11?9:s.ecologicalMonth===10?22:12;
 return Array.from({length:count},(_,n)=>{const left=21+rnd()*57,top=25+rnd()*48,color=s.colors[n%s.colors.length],size=4+rnd()*5;
 return `<i class="ww-tree-falling-leaf" style="--fx:${left.toFixed(1)}%;--fy:${top.toFixed(1)}%;--delay:-${(rnd()*11).toFixed(1)}s;--duration:${(5+rnd()*8).toFixed(1)}s;--leaf-size:${size.toFixed(1)}px;--leaf-color:${color}"></i>`;}).join('');
}
function sceneMarkup(lighthouseURL){
 let base;try{base=new URL(lighthouseURL,document.baseURI);}catch{base=new URL('assets/lighthouse.avif',document.baseURI);}
 const asset=name=>new URL(name,base).href;
 return `<div class="ww-tree-landscape" aria-hidden="true"><img class="ww-tree-mountains" src="${asset('tree-mountains.svg')}" alt="" decoding="async"><img class="ww-tree-hill" src="${asset('tree-hill.svg')}" alt="" decoding="async"><div class="ww-tree-wrap"><div class="ww-tree-foliage-slot">${canopy(7)}</div><img class="ww-tree-trunk" src="${asset('tree-trunk.svg')}" alt="" decoding="async">${snowCaps}<div class="ww-tree-fall-slot">${falling(10)}</div></div></div>`;
}
function paintMonth(scene,month,latitude=50){
 const data=stage(month,latitude);
 const foliage=scene.querySelector('.ww-tree-foliage-slot'),fall=scene.querySelector('.ww-tree-fall-slot');
 if(!foliage||!fall)return data;
 if(scene.dataset.treeMonth===String(data.month)&&scene.dataset.treeHemisphere===data.hemisphere)return data;
 foliage.innerHTML=canopy(data.month,latitude);fall.innerHTML=falling(data.month,latitude);
 scene.dataset.treeMonth=String(data.month);scene.dataset.treeHemisphere=data.hemisphere;scene.dataset.season=data.season;
 return data;
}
root.AYYYWeatherTree={STAGES,stage,canopy,falling,sceneMarkup,paintMonth};
})(typeof window!=='undefined'?window:globalThis);
if(typeof module!=='undefined' && module.exports)module.exports=(typeof window!=='undefined'?window:globalThis).AYYYWeatherTree;
